type StubNode = {id: string; data?: Record<string, unknown>; type?: string};
type StubEdge = {id: string; source: string; target: string; type?: string; data?: Record<string, unknown>};
type NodeRenderProps = {id: string; data: Record<string, unknown>; type: string};
type EdgeRenderProps = {id: string; data: Record<string, unknown>};
type StubReactFlowProps = {nodes: StubNode[]; edges?: StubEdge[]; className?: string; nodeTypes?: Record<string, React.ComponentType<NodeRenderProps>>; edgeTypes?: Record<string, React.ComponentType<EdgeRenderProps>>; onNodeClick?: (e: React.MouseEvent<HTMLDivElement>, n: StubNode) => void; onPaneClick?: (e: React.MouseEvent<HTMLDivElement>) => void};

vi.mock('@xyflow/react', async () => {
    const actual = await vi.importActual<typeof import('@xyflow/react')>('@xyflow/react');
    return {
        ...actual,
        ReactFlow: ({nodes, edges, className, nodeTypes, edgeTypes, onNodeClick, onPaneClick}: StubReactFlowProps) => (
            <div className={className} data-testid='react-flow-mock' onClick={onPaneClick}>
                {nodes.map((node) => {
                    const nodeType = node.type ?? 'default';
                    const Custom = nodeTypes?.[nodeType];
                    return <div key={node.id} data-node-id={node.id} onClick={(e) => {
                        e.stopPropagation(); onNodeClick?.(e, node);
                    }}>{Custom ? <Custom data={node.data ?? {}} id={node.id} type={nodeType} /> : null}</div>;
                })}
                <ul data-testid='react-flow-mock-edges'>{(edges ?? []).map((edge) => {
                    const Custom = edge.type ? edgeTypes?.[edge.type] : undefined;
                    return <li key={edge.id} data-source={edge.source} data-target={edge.target}>{Custom ? <Custom data={edge.data ?? {}} id={edge.id} /> : null}</li>;
                })}</ul>
            </div>
        ),
        Background: () => null, Handle: () => null, BaseEdge: () => null,
        EdgeLabelRenderer: ({children}: {children: React.ReactNode}) => <>{children}</>,
        getSmoothStepPath: () => ['M 0 0', 0, 0]
    };
});

